window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b609b34a9f11ca18"]={"versions": [{"id": "FIG-b609b34a9f11ca18", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Communication Stack (ComStack).</li>\n<li><strong>Funktionale Einordnung:</strong> Darstellung des Pull-basierten Datenübertragungsmodells (<em>TriggerTransmit</em>) für LIN-I-PDUs (ausgenommen <em>LIN Sporadic Frames</em>). Das Diagramm spezifiziert die Weiterleitung der Abfrage von der unteren Schnittstellenschicht (<code>LinIf</code>) über den PDU Router (<code>PduR</code>) an die obere Schicht (<code>Com</code>) sowie die anschließende Übertragungsbestätigung (<em>TxConfirmation</em>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Module / Lifelines:</strong></li>\n<li><code>«module» LinIf</code> (LIN Interface): Schnittstelle zum LIN-Treiber/Bus; kontrolliert zeitgesteuerte Abläufe anhand der LIN Schedule Table.</li>\n<li><code>«module» PduR</code> (PDU Router): Vermittlungsschicht für I-PDUs zwischen transportunabhängigen oberen Schichten und bus-spezifischen unteren Schnittstellen.</li>\n<li><code>«module» Com</code> (AUTOSAR COM): Signal- und I-PDU-Verwaltung der oberen Schicht; hält die aktuellen Sendedaten im internen Puffer.</li>\n<li><strong>Schnittstellen & Service-APIs:</strong></li>\n<li><code>PduR_&lt;User:Lo&gt;TriggerTransmit(PduIdType, PduInfoType*)</code>: Untere Interface-Abfrage (hier konkret: <code>PduR_LinIfTriggerTransmit</code>), ausgelöst durch den LIN-Scheduler zur Abholung der I-PDU-Nutzdaten.</li>\n<li><code>Com_TriggerTransmit(PduIdType, PduInfoType*)</code>: Obere Interface-Abfrage an das Modul <code>Com</code> zum synchronen Befüllen des übergebenen Puffers (<code>PduInfoPtr-&gt;SduDataPtr</code>) und Setzen der Länge (<code>SduLength</code>).</li>\n<li><code>PduR_&lt;User:Lo&gt;TxConfirmation(PduIdType, Std_ReturnType)</code>: Asynchrone Sendebestätigung von <code>LinIf</code> an <code>PduR</code> nach erfolgreichem Frame-Transfer auf dem Bus.</li>\n<li><code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>: Weiterleitung der Bestätigung an <code>Com</code> zur Quittierung und ggf. Signal-Ablaufüberwachung (Tx-Deadline-Monitoring).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Triggerung via Schedule Table (LinIf):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zu einem im LIN-Schedule definierten Zeitschlitz initiiert <code>LinIf</code> synchron den Datenaustausch via <code>PduR_&lt;User:Lo&gt;TriggerTransmit</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Weiterleitung & Pufferkopie (PduR -> Com):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>PduR</code> routet den Aufruf direkt und synchron via <code>Com_TriggerTransmit</code> an das Modul <code>Com</code>.</li>\n<li><code>PduR</code> führt keine Pufferung durch (<em>\"No buffering is made in PduR\"</em>).</li>\n<li><code>Com</code> kopiert die aktuellen Nutzdaten atomar in den bereitgestellten Puffer (<code>copy buffer()</code>) und signalisiert Erfolg (<code>E_OK</code>) bzw. Fehler (<code>E_NOT_OK</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Rückkehrpfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rücksprung der synchronen Callbacks über <code>PduR</code> zurück an <code>LinIf</code>. <code>LinIf</code> übergibt die Daten an den LIN-Treiber (<code>Lin</code>) für den Frame-Header/Response-Zyklus auf dem Bus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>TxConfirmation (Asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreichem Senden des LIN-Frames auf dem Bus ruft <code>LinIf</code> <code>PduR_&lt;User:Lo&gt;TxConfirmation</code> auf.</li>\n<li><code>PduR</code> delegiert den Aufruf synchron via <code>Com_TxConfirmation</code> an <code>Com</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsaspekte (<code>PduR</code> & <code>Com</code>):</strong></li>\n<li>Für diese Routing-Pfade ist im <code>PduR</code> der PDU-Typ auf TriggerTransmit zu konfigurieren (<code>PduRQueueDepth = 0</code>; kein FIFO/Puffer-Support im PduR für diesen Pfad).</li>\n<li>Im <code>Com</code> muss für die betroffene I-PDU <code>ComIPduSignalProcessing</code> beachtet werden (TriggerTransmit operiert typischerweise im Kontext der <code>LinIf</code>/Scheduler-Task oder ISR).</li>\n<li><strong>Echtzeit- und Reentrancy-Anforderungen:</strong></li>\n<li><code>Com_TriggerTransmit</code> wird im Interrupt- oder Scheduler-Task-Kontext des LIN-Stacks aufgerufen. Der Signalpuffer-Kopiervorgang (<code>copy buffer()</code>) muss extrem kurz und konsistent sein (Interrupt-Sperre / Locks gegen parallele <code>Com_SendSignal</code>-Updates).</li>\n<li><strong>Abgrenzung zu LIN Sporadic Frames:</strong></li>\n<li>Bei <em>LIN Sporadic Frames</em> wird die Übertragung aktiv über <code>PduR_ComTransmit</code> bzw. <code>LinIf_Transmit</code> angefordert (Push-Prinzip), sobald Datenänderungen vorliegen.</li>\n<li>Das hier gezeigte Pull-Muster gilt strikt für reguläre Frames (Unconditional Frames etc.), bei denen der Master-Schedule den Zeitpunkt der Abfrage autonom diktiert.</li>\n</ul>"}, {"id": "FIG-5d1ea3d9638d02f3", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Communication Stack (ComStack).</li>\n<li><strong>Funktionale Einordnung:</strong> Darstellung des Pull-basierten Datenübertragungsmodells (<em>TriggerTransmit</em>) für LIN-I-PDUs (ausgenommen <em>LIN Sporadic Frames</em>). Das Diagramm spezifiziert die Weiterleitung der Abfrage von der unteren Schnittstellenschicht (<code>LinIf</code>) über den PDU Router (<code>PduR</code>) an die obere Schicht (<code>Com</code>) sowie die anschließende Übertragungsbestätigung (<em>TxConfirmation</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Module / Lifelines:</strong></li>\n<li><code>«module» LinIf</code> (LIN Interface): Schnittstelle zum LIN-Treiber/Bus; kontrolliert zeitgesteuerte Abläufe anhand der LIN Schedule Table.</li>\n<li><code>«module» PduR</code> (PDU Router): Vermittlungsschicht für I-PDUs zwischen transportunabhängigen oberen Schichten und bus-spezifischen unteren Schnittstellen.</li>\n<li><code>«module» Com</code> (AUTOSAR COM): Signal- und I-PDU-Verwaltung der oberen Schicht; hält die aktuellen Sendedaten im internen Puffer.</li>\n<li><strong>Schnittstellen & Service-APIs:</strong></li>\n<li><code>PduR_&lt;User:Lo&gt;TriggerTransmit(PduIdType, PduInfoType*)</code>: Untere Interface-Abfrage (hier konkret: <code>PduR_LinIfTriggerTransmit</code>), ausgelöst durch den LIN-Scheduler zur Abholung der I-PDU-Nutzdaten.</li>\n<li><code>Com_TriggerTransmit(PduIdType, PduInfoType*)</code>: Obere Interface-Abfrage an das Modul <code>Com</code> zum synchronen Befüllen des übergebenen Puffers (<code>PduInfoPtr-&gt;SduDataPtr</code>) und Setzen der Länge (<code>SduLength</code>).</li>\n<li><code>PduR_&lt;User:Lo&gt;TxConfirmation(PduIdType, Std_ReturnType)</code>: Asynchrone Sendebestätigung von <code>LinIf</code> an <code>PduR</code> nach erfolgreichem Frame-Transfer auf dem Bus.</li>\n<li><code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>: Weiterleitung der Bestätigung an <code>Com</code> zur Quittierung und ggf. Signal-Ablaufüberwachung (Tx-Deadline-Monitoring).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Triggerung via Schedule Table (LinIf):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zu einem im LIN-Schedule definierten Zeitschlitz initiiert <code>LinIf</code> synchron den Datenaustausch via <code>PduR_&lt;User:Lo&gt;TriggerTransmit</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Weiterleitung & Pufferkopie (PduR -> Com):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>PduR</code> routet den Aufruf direkt und synchron via <code>Com_TriggerTransmit</code> an das Modul <code>Com</code>.</li>\n<li><code>PduR</code> führt keine Pufferung durch (<em>\"No buffering is made in PduR\"</em>).</li>\n<li><code>Com</code> kopiert die aktuellen Nutzdaten atomar in den bereitgestellten Puffer (<code>copy buffer()</code>) und signalisiert Erfolg (<code>E_OK</code>) bzw. Fehler (<code>E_NOT_OK</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Rückkehrpfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rücksprung der synchronen Callbacks über <code>PduR</code> zurück an <code>LinIf</code>. <code>LinIf</code> übergibt die Daten an den LIN-Treiber (<code>Lin</code>) für den Frame-Header/Response-Zyklus auf dem Bus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>TxConfirmation (Asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreichem Senden des LIN-Frames auf dem Bus ruft <code>LinIf</code> <code>PduR_&lt;User:Lo&gt;TxConfirmation</code> auf.</li>\n<li><code>PduR</code> delegiert den Aufruf synchron via <code>Com_TxConfirmation</code> an <code>Com</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsaspekte (<code>PduR</code> & <code>Com</code>):</strong></li>\n<li>Für diese Routing-Pfade ist im <code>PduR</code> der PDU-Typ auf TriggerTransmit zu konfigurieren (<code>PduRQueueDepth = 0</code>; kein FIFO/Puffer-Support im PduR für diesen Pfad).</li>\n<li>Im <code>Com</code> muss für die betroffene I-PDU <code>ComIPduSignalProcessing</code> beachtet werden (TriggerTransmit operiert typischerweise im Kontext der <code>LinIf</code>/Scheduler-Task oder ISR).</li>\n<li><strong>Echtzeit- und Reentrancy-Anforderungen:</strong></li>\n<li><code>Com_TriggerTransmit</code> wird im Interrupt- oder Scheduler-Task-Kontext des LIN-Stacks aufgerufen. Der Signalpuffer-Kopiervorgang (<code>copy buffer()</code>) muss extrem kurz und konsistent sein (Interrupt-Sperre / Locks gegen parallele <code>Com_SendSignal</code>-Updates).</li>\n<li><strong>Abgrenzung zu LIN Sporadic Frames:</strong></li>\n<li>Bei <em>LIN Sporadic Frames</em> wird die Übertragung aktiv über <code>PduR_ComTransmit</code> bzw. <code>LinIf_Transmit</code> angefordert (Push-Prinzip), sobald Datenänderungen vorliegen.</li>\n<li>Das hier gezeigte Pull-Muster gilt strikt für reguläre Frames (Unconditional Frames etc.), bei denen der Master-Schedule den Zeitpunkt der Abfrage autonom diktiert.</li>\n</ul>"}], "trans": [{"from": "FIG-b609b34a9f11ca18", "to": "FIG-5d1ea3d9638d02f3", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
